const tests=[
 {id:'balance',title:'Мій емоційний баланс',category:'Емоції',desc:'Зупиніться на мить і поміркуйте про свій стан та відновлення.',label:'Емоції та стрес',questions:[['Я знаходжу час, щоб відновити сили.',false],['Мені складно відволіктися від щоденних турбот.',true],['Я помічаю та можу назвати свої емоції.',false],['Наприкінці дня я почуваюся виснажено.',true],['У мене є заняття, які допомагають відпочити.',false],['Я дозволяю собі робити паузи без почуття провини.',false]]},
 {id:'self',title:'Знайомство із собою',category:'Особистість',desc:'Дослідіть, як ви прислухаєтеся до своїх потреб і власних рішень.',label:'Особистість',questions:[['Я розумію, що для мене зараз важливо.',false],['Мені важко назвати свої сильні сторони.',true],['Мої щоденні рішення відповідають моїм цінностям.',false],['Я часто погоджуюся всупереч власним потребам.',true],['Я можу помітити, коли потребую підтримки.',false],['Я виділяю час для того, що мене цікавить.',false]]},
 {id:'career',title:'Ресурс у роботі',category:'Кар’єра',desc:'Подивіться на свій робочий ритм, навантаження та джерела енергії.',label:'Кар’єра та розвиток',questions:[['Я маю достатньо часу для відпочинку після роботи.',false],['Робочі справи постійно займають мій вільний час.',true],['Я розумію пріоритети своїх робочих завдань.',false],['Мені складно встановлювати межі навантаження.',true],['Я можу звернутися по допомогу в роботі.',false],['У роботі є завдання, які викликають мій інтерес.',false]]}
];
const key='prostir-v1';let storageOk=true;function read(){try{return JSON.parse(localStorage.getItem(key))||{history:[],drafts:{}}}catch{storageOk=false;return{history:[],drafts:{}}}}let state=read();if(!Array.isArray(state.history)||!state.drafts)state={history:[],drafts:{}};function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{storageOk=false}}const $=s=>document.querySelector(s),modal=$('#modal'),body=$('#modalBody');let filter='all',query='',active=null,index=0,answers=[];
function show(html){body.innerHTML=html;if(!modal.open)modal.showModal()}function render(){const found=tests.filter(t=>(filter==='all'||t.category===filter)&&(t.title+' '+t.desc+' '+t.label).toLocaleLowerCase('uk').includes(query));$('#cards').innerHTML=found.map(t=>`<article class="card"><div class="card-art"><span class="card-badge">Демо · безкоштовно</span><div class="shape"></div></div><div class="card-content"><div class="meta">${t.label}</div><h3>${t.title}</h3><p>${t.desc}</p><div class="card-bottom"><span>◷ 2–3 хв · 6 запитань</span><button data-start="${t.id}">Почати ↗</button></div></div></article>`).join('')||'<p class="empty">За цим запитом опитувань немає. Спробуйте іншу тему або назву.</p>'}
$('#filters').onclick=e=>{if(!e.target.dataset.filter)return;filter=e.target.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));render()};$('#search').oninput=e=>{query=e.target.value.toLocaleLowerCase('uk');render()};$('#cards').onclick=e=>{const b=e.target.closest('[data-start]');if(b)intro(b.dataset.start)};
function intro(id){active=tests.find(t=>t.id===id);const draft=state.drafts[id];show(`<div class="eyebrow">ПЕРШИЙ КРОК ДО СЕБЕ</div><h2>${active.title}</h2><p>Подумайте про останні 7 днів. Оцініть, наскільки кожне твердження відповідає вашому досвіду.</p><p class="small">Це авторське демонстраційне опитування для перевірки роботи платформи. Воно не є валідованою психологічною методикою та не встановлює діагнозів. Результат — лише підсумок ваших відповідей.</p><p class="small">Відповіді та історія зберігаються у цьому браузері. Не використовуйте спільний пристрій для приватних відповідей.</p><button class="primary" id="begin">${draft?'Продовжити опитування':'Почати опитування'} →</button>`);$('#begin').onclick=()=>{answers=draft?.answers?.slice()||[];index=Math.min(draft?.index||0,active.questions.length-1);question()}}
const options=['Зовсім не відповідає','Радше не відповідає','Частково відповідає','Радше відповідає','Повністю відповідає'];
function question(){show(`<div class="eyebrow">${active.title}</div><progress value="${answers.filter(Number.isFinite).length}" max="6"></progress><p class="small">Запитання ${index+1} з 6 · ${storageOk?'Прогрес збережено на пристрої':'Збереження недоступне в цьому браузері'}</p><h2>${active.questions[index][0]}</h2><div class="answers">${options.map((s,i)=>`<button class="answer ${answers[index]===i+1?'selected':''}" data-value="${i+1}" aria-pressed="${answers[index]===i+1}">${i+1}. ${s}</button>`).join('')}</div><div class="dialog-actions"><button class="outline" id="back" ${index===0?'disabled':''}>← Назад</button><span class="small">Клавіші 1–5</span><button class="primary" id="next" ${!answers[index]?'disabled':''}>${index===5?'Мій результат':'Далі →'}</button></div>`);body.querySelectorAll('[data-value]').forEach(b=>b.onclick=()=>choose(+b.dataset.value));$('#back').onclick=()=>{index--;persist();question()};$('#next').onclick=()=>{if(!answers[index])return;if(index<5){index++;persist();question()}else finish()}}
function persist(){state.drafts[active.id]={answers,index};save()}function choose(value){answers[index]=value;persist();question();$('#next').focus()}
function score(test,values){if(values.length!==test.questions.length||values.some(v=>!Number.isInteger(v)||v<1||v>5))throw Error('Неповні відповіді');const raw=values.reduce((sum,v,i)=>sum+(test.questions[i][1]?6-v:v),0);return{raw,percent:Math.round((raw-6)/24*100)}}
function finish(){const result={id:active.id,...score(active,answers),date:new Date().toISOString()};state.history.unshift(result);delete state.drafts[active.id];save();active=null;showResult(result)}
function showResult(r){const test=tests.find(t=>t.id===r.id);show(`<div class="eyebrow">ПІДСУМОК ВАШИХ ВІДПОВІДЕЙ</div><h2>${test.title}</h2><div class="score">${r.percent}<small> / 100</small></div><p>Ваші відповіді відповідають ${r.raw} балам із 30 можливих. Після врахування зворотних тверджень результат переведено у шкалу 0–100.</p><p class="small">Вищий показник означає більшу згоду з твердженнями про доступні ресурси. Для цієї демонстрації немає клінічних порогів, нормативів або оцінки «добре / погано».</p><p>Для роздумів: що з описаного вже підтримує вас, а чому хочеться приділити більше уваги?</p><p class="small">${storageOk?'Результат збережений лише в цьому браузері.':'Результат не вдалося зберегти. Ви можете завантажити його.'}</p><div class="dialog-actions"><button class="outline" id="download">Завантажити JSON ↓</button><button class="primary" id="resultHistory">Моя історія →</button></div>`);$('#download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({...r,title:test.title,notice:'Демонстраційне опитування без діагностичних норм'},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='prostir-result.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#resultHistory').onclick=history}
function history(){active=null;show(`<div class="eyebrow">МІЙ ПРОСТІР</div><h2>Історія результатів</h2><p class="small">Цей пристрій · без облікового запису · ${state.history.length} проходжень</p>${state.history.length?state.history.map((r,i)=>`<div class="history-item"><div><strong>${tests.find(t=>t.id===r.id)?.title||'Опитування'}</strong><br><span class="small">${new Date(r.date).toLocaleString('uk-UA')}</span></div><button class="outline" data-result="${i}">${r.percent} / 100 ↗</button></div>`).join(''):'<p>Тут з’являться ваші завершені опитування. Оберіть перше в каталозі.</p>'}${state.history.length?'<p><button class="text small" id="clear">Видалити історію та чернетки з пристрою</button></p>':''}`);body.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>showResult(state.history[+b.dataset.result]));if($('#clear'))$('#clear').onclick=()=>{show('<h2>Видалити всі локальні дані?</h2><p>Історія результатів та незавершені відповіді будуть видалені з цього браузера.</p><div class="dialog-actions"><button class="outline" id="cancelClear">Залишити дані</button><button class="primary" id="confirmClear">Видалити</button></div>');$('#cancelClear').onclick=history;$('#confirmClear').onclick=()=>{state={history:[],drafts:{}};save();history()}}}
$('#closeModal').onclick=()=>modal.close();modal.addEventListener('close',()=>active=null);document.addEventListener('keydown',e=>{if(modal.open&&active&&body.querySelector('.answers')&&/^[1-5]$/.test(e.key)){e.preventDefault();choose(+e.key)}});$('#startHero').onclick=$('#startBottom').onclick=()=>intro('balance');$('#historyBtn').onclick=$('#account').onclick=history;$('#privacy').onclick=()=>show('<h2>Ваші дані та приватність</h2><p>У цьому прототипі відповіді, чернетки й результати зберігаються локально у вашому браузері. Синхронізації з обліковим записом немає. Очищення даних браузера видалить історію.</p><p>Видалити локальні дані можна в розділі «Мої результати». На спільному пристрої інші користувачі браузера можуть бачити вашу історію.</p><p class="small">Шрифт завантажується з Google Fonts; хостинг обробляє технічні запити відвідування. Платежі, авторизація та надсилання відповідей на сервер у прототипі не реалізовані.</p>');render();
